"""Plot the fixed-density non-equilibrium tests generated by make -C test noneq."""

import argparse
from pathlib import Path

import matplotlib

if __name__ == "__main__":
    matplotlib.use("Agg")

import matplotlib.pyplot as plt
from matplotlib.ticker import FuncFormatter, LogLocator
import numpy as np

from plot_style import BLACK, BLUE, GRAY, GREEN, ORANGE, PLOT_STYLE, PURPLE, SKY


PLOT_DIR = Path(__file__).resolve().parent
RATE_LABEL = r"Rate [erg cm$^{-3}$ s$^{-1}$]"
PHASES = ("on", "off")
TEMPERATURE = ("Temperature [K]", (("T", "Temperature", BLACK, "-"),))
IONIZING_PANELS = (
    TEMPERATURE,
    ("H and He fractions", (("HII", "H II", BLUE, "-"), ("HeI", "He I", GRAY, ":"),
                           ("HeII", "He II", ORANGE, "-"), ("HeIII", "He III", PURPLE, "-"),
                           ("xe", r"$n_e/n_{\rm H}$", BLACK, "--"))),
    ("Carbon fractions", (("CI", "C I", GRAY, ":"), ("CII", "C II", BLUE, "-"), ("CIII", "C III", ORANGE, "-"))),
    ("Oxygen fractions", (("OI", "O I", GRAY, ":"), ("OII", "O II", BLUE, "-"), ("OIII", "O III", ORANGE, "-"))),
    (RATE_LABEL, (("L_tot", "Total cooling", BLACK, "-"), ("H_tot", "Total heating", GRAY, "--"),
                  ("L_CII158", "[C II] 158 μm", GREEN, "-"), ("L_OII", "[O II]", BLUE, "-"),
                  ("L_OIII", "[O III]", ORANGE, "-"))),
)
FUV_PANELS = (
    TEMPERATURE,
    ("Hydrogen fractions", (("HI", "H I", BLUE, "-"), ("H2", "H₂ nuclei", GREEN, "-"))),
    ("Carbon fractions", (("CI", "C I", GRAY, ":"), ("CII", "C II", BLUE, "-"))),
    (RATE_LABEL, (("L_tot", "Total cooling", BLACK, "-"), ("H_tot", "Total heating", GRAY, "--"),
                  ("L_CII158", "[C II] 158 μm", GREEN, "-"), ("L_H2", "H₂ cooling", BLUE, "-"),
                  ("H_H2", "H₂ heating", ORANGE, "--"))),
)
COOLING_COMPONENTS = {
    "ionizing": (("L_CII158", "[C II] 158 μm", GREEN), ("L_OII", "[O II]", BLUE),
                 ("L_OIII", "[O III]", ORANGE)),
    "fuv": (("L_CII158", "[C II] 158 μm", GREEN), ("L_H2", "H₂", BLUE)),
}
TOTAL_COOLING = (
    ("L_tot", "Non-equilibrium", BLACK, "-"),
    ("eq_L_tot", "Equilibrium composition · shared rates", BLUE, "--"),
    ("eq_native_L_tot", "Equilibrium composition · native rates", ORANGE, ":"),
)
BENCHMARK_METHODS = (("equilibrium", "Equilibrium", BLUE),
                     ("nonequilibrium", "Non-equilibrium", ORANGE))
LOOKUP_BENCHMARK_METHODS = (("nonequilibrium", "Temperature lookup", BLUE),
                            ("nonequilibrium_direct", "Direct evaluation", ORANGE))
BENCHMARK_TITLES = {"ionizing": "Ionizing light", "recombining": "Recombining gas", "fuv": "Far-ultraviolet light"}
COOLING_TITLES = {"ionizing": "ionizing pulse", "fuv": "far-ultraviolet pulse"}
ABUNDANCE_FIELDS = ("HI", "HII", "H2", "HeI", "HeII", "HeIII", "CI", "CII", "CIII", "OI", "OII", "OIII", "xe")


def read_csv(path):
    return np.genfromtxt(path, names=True, delimiter=",", dtype=None, encoding="utf-8", ndmin=1)


def pulse_phases(evolution, scenario):
    rows = evolution[evolution["scenario"] == scenario]
    phases = [rows[(rows["phase"] == phase) & (rows["phase_time_yr"] > 0.0)] for phase in PHASES]
    if not all(len(data) for data in phases):
        raise ValueError(f"Missing illuminated or dark time series for {scenario}")
    return phases


def plot_pulse(evolution, scenario, title, panels):
    phases = pulse_phases(evolution, scenario)
    fig, axes = plt.subplots(len(panels), 2, sharex="col", sharey="row",
                             figsize=(11, 1.95*len(panels)+0.7), layout="constrained")
    fig.suptitle(title + rf" · $n_{{\rm H}}={phases[0][0]['nH']:g}$ cm$^{{-3}}$")
    for column, (heading, data) in enumerate(zip(("Illuminated", "After turn-off"), phases)):
        axes[0, column].set_title(heading, loc="left")
        for row, (ylabel, series) in enumerate(panels):
            ax = axes[row, column]
            for field, label, color, line in series:
                values = np.ma.masked_less_equal(data[field], 0) if ylabel == RATE_LABEL else data[field]
                if np.ma.count(values):
                    ax.plot(data["phase_time_yr"], values, color=color, ls=line, lw=1.65, label=label)
            ax.set_xscale("log")
            if row == 0:
                ax.set_yscale("log")
            elif ylabel == RATE_LABEL:
                peak = max(data[field].max() for data in phases for field, *_ in series)
                final_cooling = phases[-1]["L_tot"][-1]
                floor = min(peak*1e-7, final_cooling*0.5) if final_cooling > 0 else peak*1e-7
                ax.set(yscale="log", ylim=(floor, peak*2))
            else:
                ymax = max(1.0, max(data[field].max() for data in phases for field, *_ in series))
                ax.set_ylim(-0.035, 1.06*ymax)
            if column == 0:
                ax.set_ylabel(ylabel)
                if row > 0:
                    ax.legend(loc="best", ncols=2, fontsize=8)
        axes[-1, column].set_xlabel("Time since turn-on [yr]" if column == 0 else "Time since turn-off [yr]")
    if max(data["T"].max() for data in phases) / min(data["T"].min() for data in phases) < 100:
        # Label intermediate ticks for modest temperature ranges.
        axes[0, 0].yaxis.set_major_locator(LogLocator(base=10, subs=(1, 2, 5)))
        axes[0, 0].yaxis.set_major_formatter(FuncFormatter(lambda value, _: f"{value:g}"))
    return fig


def plot_cooling_comparison(evolution, scenario):
    phases = pulse_phases(evolution, scenario)
    components = COOLING_COMPONENTS[scenario]
    peak = max(data[key].max() for data in phases for field, _, _ in components
               for key in (field, "eq_" + field))
    fig, axes = plt.subplots(3, 2, sharex="col", sharey="row", figsize=(11, 7.8), layout="constrained")
    fig.suptitle(f"Cooling at matched temperature · {COOLING_TITLES[scenario]}")
    for column, data in enumerate(phases):
        total, lines, ratio = axes[:, column]
        time = data["phase_time_yr"]
        total.set_title("Illuminated" if column == 0 else "After turn-off", loc="left")
        for field, label, color, style in TOTAL_COOLING:
            total.plot(time, np.ma.masked_less_equal(data[field], 0), label=label, color=color, ls=style, lw=1.8)
        for field, label, color in components:
            lines.plot(time, np.ma.masked_less_equal(data[field], 0), label=label, color=color, lw=1.6)
            lines.plot(time, np.ma.masked_less_equal(data["eq_" + field], 0), color=color, ls="--", lw=1.6)

        ratio.axhline(1.0, color=GRAY, lw=1.0, alpha=0.5)
        for field, _, color, style in TOTAL_COOLING[1:]:
            positive = (data["L_tot"] > 0) & (data[field] > 0)
            values = np.full(len(data), np.nan)
            np.divide(data["L_tot"], data[field], out=values, where=positive)
            ratio.plot(time, values, color=color, ls=style, lw=1.8)

        for ax in (total, lines, ratio):
            ax.set(xscale="log", yscale="log")
        ratio.set_xlabel("Time since turn-on [yr]" if column == 0 else "Time since turn-off [yr]")

    axes[0, 0].set_ylabel("Total cooling [erg cm$^{-3}$ s$^{-1}$]")
    axes[1, 0].set_ylabel("Component cooling [erg cm$^{-3}$ s$^{-1}$]")
    if peak > 0:
        axes[1, 0].set_ylim(peak * 1.0e-12, peak * 2.0)
    axes[2, 0].set_ylabel("Non-equilibrium / equilibrium")
    axes[0, 0].legend(loc="best", fontsize=8)
    axes[1, 0].legend(loc="best", fontsize=8, ncols=2, title="Solid · non-equilibrium\nDashed · equilibrium (shared rates)",
                      title_fontsize=8)
    return fig


def benchmark_timings(data, methods=BENCHMARK_METHODS):
    timings = {}
    for scenario in dict.fromkeys(data["scenario"]):
        gas = data[data["scenario"] == scenario]
        for step in np.unique(gas["dt_yr"]):
            rows = [np.sort(gas[(gas["dt_yr"] == step) & (gas["method"] == mode)], order="trial")
                    for mode, _, _ in methods]
            trials = rows[0]["trial"]
            if not len(trials) or len(np.unique(trials)) != len(trials) or not np.array_equal(trials, rows[1]["trial"]):
                raise ValueError(f"Mismatched benchmark trials for {scenario}, dt={step:g} yr")
            stats = []
            for row in rows:
                if not np.all((row["calls"] > 0) & np.isfinite(row["elapsed_s"]) & (row["elapsed_s"] > 0)):
                    raise ValueError(f"Invalid benchmark calls or elapsed time for {scenario}, dt={step:g} yr")
                times = 1.0e6 * row["elapsed_s"] / row["calls"]
                stats.append((np.median(times), times.min(), times.max()))
            timings[scenario, step] = stats
    if not timings:
        raise ValueError("No timings in the non-equilibrium benchmark")
    return timings


def plot_benchmark(timings, methods=BENCHMARK_METHODS, *, title="Cost of one fixed-density energy update",
                   ratio_label="Non-equilibrium / equilibrium", ratio_scale="log"):
    scenarios = tuple(dict.fromkeys(scenario for scenario, _ in timings))
    fig, axes = plt.subplots(2, len(scenarios), sharex="col", sharey="row", squeeze=False,
                             figsize=(max(5, 3.55*len(scenarios)), 5.6), layout="constrained")
    fig.suptitle(title)
    for index, scenario in enumerate(scenarios):
        time, ratio = axes[:, index]
        steps = np.array([step for gas, step in timings if gas == scenario])
        stats = np.array([timings[scenario, step] for step in steps])
        time.set_title(BENCHMARK_TITLES.get(scenario, scenario.replace("_", " ").capitalize()))
        for i, (_, label, color) in enumerate(methods):
            median, low, high = stats[:, i, :].T
            time.errorbar(steps, median, yerr=(median-low, high-median), color=color,
                          marker="o", capsize=3, label=label)
        ratio.axhline(1.0, color=GRAY, lw=1.0, alpha=0.5)
        ratio.plot(steps, stats[:, 1, 0]/stats[:, 0, 0], color=BLACK, marker="o")
        time.set(yscale="log")
        ratio.set(xscale="log", yscale=ratio_scale, xlabel="Timestep [yr]")
        ratio.set_xticks(steps, [f"{step:,.0f}" for step in steps])
    axes[0, 0].set_ylabel("Wall time per update [μs]")
    axes[1, 0].set_ylabel(ratio_label)
    axes[0, 0].legend(fontsize=8)
    return fig


def plot_lookup_benchmark(timings):
    return plot_benchmark(timings, LOOKUP_BENCHMARK_METHODS,
                          title="Cost of temperature lookup in non-equilibrium updates",
                          ratio_label="Speedup · direct / lookup", ratio_scale="linear")


def lookup_differences(lookup, direct):
    keys = ("scenario", "phase", "time_yr", "phase_time_yr", "nH", "Nt", "NLyn", "G0", "Zd")
    if not all(np.array_equal(lookup[key], direct[key]) for key in keys):
        raise ValueError("Temperature lookup and direct evaluation have different snapshot coordinates")

    errors = {
        "T": np.abs(lookup["T"]-direct["T"])/direct["T"],
        "fraction": np.maximum.reduce([np.abs(lookup[field]-direct[field]) for field in ABUNDANCE_FIELDS]),
    }
    for field in dict.fromkeys(["L_tot", *(term[0] for terms in COOLING_COMPONENTS.values() for term in terms)]):
        reference = np.abs(direct[field])
        errors[field] = np.full(len(direct), np.nan)
        for scenario in COOLING_COMPONENTS:
            rows = direct["scenario"] == scenario
            floor = 1.0e-6*reference[rows].max() if field != "L_tot" else 0.0
            active = rows & (reference > floor)
            errors[field][active] = np.abs(lookup[field][active]-direct[field][active])/reference[active]
    return errors


def plot_lookup_differences(evolution, errors, scenario):
    fig, axes = plt.subplots(3, 2, sharex="col", sharey="row", figsize=(10.5, 7.0), layout="constrained")
    fig.suptitle(f"Temperature lookup vs direct evaluation · {COOLING_TITLES[scenario]}")
    linear_threshold = 1e-12
    markers = {"ls": "none", "marker": "o", "ms": 2.6, "alpha": 0.8}
    cooling_series = (("L_tot", "Total", BLACK), *COOLING_COMPONENTS[scenario])
    shown = (evolution["scenario"] == scenario) & (evolution["phase_time_yr"] > 0)
    for column, phase in enumerate(PHASES):
        mask = shown & (evolution["phase"] == phase)
        time = evolution["phase_time_yr"][mask]
        temperature, abundance, cooling = axes[:, column]
        temperature.set_title("Illuminated" if column == 0 else "After turn-off", loc="left")
        temperature.plot(time, errors["T"][mask], color=BLACK, **markers)
        abundance.plot(time, errors["fraction"][mask], color=PURPLE, **markers)
        for field, label, color in cooling_series:
            cooling.plot(time, errors[field][mask], color=color, label=label, **markers)
        for ax in (temperature, abundance, cooling):
            ax.set_xscale("log")
            ax.set_yscale("symlog", linthresh=linear_threshold)
        cooling.set_xlabel("Time since turn-on [yr]" if column == 0 else "Time since turn-off [yr]")

    for ax, fields in zip(axes[:, 0], [("T",), ("fraction",), tuple(term[0] for term in cooling_series)]):
        values = np.concatenate([errors[field][shown] for field in fields])
        peak = np.max(values, where=np.isfinite(values), initial=linear_threshold)
        ax.set_ylim(-0.12*linear_threshold, 1.6*peak)
    axes[0, 0].set_ylabel("Temperature\nrelative difference")
    axes[1, 0].set_ylabel("Species and electron fractions\nmaximum absolute difference")
    axes[2, 0].set_ylabel("Cooling rate\nrelative difference")
    axes[2, 0].legend(loc="best", fontsize=8, ncols=2)
    return fig


def plot_step_errors(ax, convergence, field, ylabel, limit):
    steps = np.unique(convergence["dt_yr"])
    for h2, color, marker, shift in ((0, BLUE, "o", 0.90), (1, ORANGE, "s", 1.11)):
        medians = []
        for step in steps:
            values = convergence[field][(convergence["H2"] == h2) & (convergence["dt_yr"] == step)]
            values = np.maximum(values, 1.0e-16)
            ax.scatter(np.full(len(values), step*shift), values, color=color, marker=marker,
                       s=14, alpha=0.28, linewidths=0)
            medians.append(np.median(values))
        ax.scatter(steps*shift, medians, color=color, marker=marker, s=30,
                   label="H₂ off · median" if h2 == 0 else "H₂ on · median", zorder=3)
    ax.axhline(limit, color=GRAY, ls=":", lw=1.0, label="Test limit")
    ax.set(xscale="log", yscale="log", xlabel="Total timestep [yr]", ylabel=ylabel, ylim=(6e-17, limit*3))
    ax.set_xticks(steps, [f"{step:,.0f}" for step in steps])


def plot_validation(recombination, convergence):
    reference = recombination[recombination["time_over_trec"] > 0]
    fig, axes = plt.subplots(2, 2, figsize=(10.5, 7), layout="constrained")
    fig.suptitle("Non-equilibrium integration checks")
    time = reference["time_over_trec"]
    abundance, analytic_error = axes[0]
    abundance.plot(time, reference["analytic_HII"], color=BLACK, lw=1.6, label="Analytic")
    abundance.plot(time, reference["HII"], color=BLUE, ls="none", marker="o", markersize=3.6,
                   markevery=8, label="EQCLib")
    abundance.set(title="Hydrogen recombination at 1000 K", xscale="log", yscale="log",
                  xlabel=r"$t/t_{\rm rec}$", ylabel="H II fraction")
    abundance.legend()
    analytic_error.plot(time, np.maximum(reference["abs_error"], 1e-16), color=SKY, lw=1.8)
    analytic_error.axhline(2.0e-6, color=GRAY, ls=":", lw=1.0, label="Test limit")
    analytic_error.set(title="Deviation from the analytic solution", xscale="log", yscale="log",
                       xlabel=r"$t/t_{\rm rec}$", ylabel="Absolute H II fraction error")
    analytic_error.legend()
    temperature, species = axes[1]
    plot_step_errors(temperature, convergence, "T_rel_error", "Relative temperature difference", 5.0e-5)
    plot_step_errors(species, convergence, "fraction_abs_error", "Maximum absolute fraction difference", 5.0e-6)
    temperature.set_title("One step vs eight · temperature", loc="left")
    species.set_title("One step vs eight · abundances", loc="left")
    temperature.legend(fontsize=8, ncols=2)
    return fig


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--data-dir", type=Path, default=PLOT_DIR.parent / "test" / "out" / "noneq")
    parser.add_argument("--output-dir", type=Path, default=PLOT_DIR / "out" / "noneq")
    args = parser.parse_args()
    try:
        evolution = read_csv(args.data_dir / "evolution.csv")
        recombination = read_csv(args.data_dir / "recombination.csv")
        convergence = read_csv(args.data_dir / "convergence.csv")
        args.output_dir.mkdir(parents=True, exist_ok=True)
        with plt.rc_context(PLOT_STYLE):
            figures = {
                "ionizing_pulse.png": plot_pulse(evolution, "ionizing", "Ionizing radiation pulse", IONIZING_PANELS),
                "fuv_pulse.png": plot_pulse(evolution, "fuv", "Far-ultraviolet radiation pulse", FUV_PANELS),
                "validation.png": plot_validation(recombination, convergence),
            }
            if "eq_native_L_tot" in evolution.dtype.names:
                for scenario in COOLING_COMPONENTS:
                    figures[f"{scenario}_cooling_comparison.png"] = plot_cooling_comparison(evolution, scenario)
            benchmark_path = args.data_dir / "benchmark.csv"
            if benchmark_path.is_file():
                benchmark = read_csv(benchmark_path)
                figures["benchmark.png"] = plot_benchmark(benchmark_timings(benchmark))
                if "nonequilibrium_direct" in benchmark["method"]:
                    timings = benchmark_timings(benchmark, LOOKUP_BENCHMARK_METHODS)
                    figures["temperature_lookup_benchmark.png"] = plot_lookup_benchmark(timings)
            direct_path = args.data_dir / "evolution_direct.csv"
            if direct_path.is_file():
                errors = lookup_differences(evolution, read_csv(direct_path))
                for scenario in COOLING_COMPONENTS:
                    figures[f"{scenario}_temperature_lookup.png"] = plot_lookup_differences(evolution, errors, scenario)
            for name, fig in figures.items():
                fig.savefig(args.output_dir / name, dpi=180)
                plt.close(fig)
    except (OSError, ValueError) as error:
        parser.error(str(error))
    print(f"Non-equilibrium plots written to {args.output_dir}")


if __name__ == "__main__":
    main()
